import{_ as d,o as e,c as l,a4 as n}from"./chunks/framework.C7iBV1LP.js";const h=JSON.parse('{"title":"Universal Keybindings ⌨️","description":"","frontmatter":{},"headers":[],"relativePath":"reference/keybindings.md","filePath":"reference/keybindings.md"}'),a={name:"reference/keybindings.md"};function r(b,t,i,o,k,s){return e(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="universal-keybindings-⌨️" tabindex="-1">Universal Keybindings ⌨️ <a class="header-anchor" href="#universal-keybindings-⌨️" aria-label="Permalink to &quot;Universal Keybindings ⌨️&quot;">​</a></h1><p>Core keybindings across Niri, Ghostty, Zellij, and Helix in Solar.</p><hr><h2 id="🌊-niri-scrollable-wayland-compositor" tabindex="-1">🌊 Niri Scrollable Wayland Compositor <a class="header-anchor" href="#🌊-niri-scrollable-wayland-compositor" aria-label="Permalink to &quot;🌊 Niri Scrollable Wayland Compositor&quot;">​</a></h2><p>The default modifier key is <kbd>Mod</kbd> (<kbd>Super</kbd> / <kbd>Windows</kbd>).</p><h3 id="window-column-management" tabindex="-1">Window &amp; Column Management <a class="header-anchor" href="#window-column-management" aria-label="Permalink to &quot;Window &amp; Column Management&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Keybinding</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Focus Left / Right</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>H</kbd> / <kbd>L</kbd> (or <kbd>←</kbd> / <kbd>→</kbd>)</td></tr><tr><td style="text-align:left;"><strong>Focus Up / Down (in column)</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>J</kbd> / <kbd>K</kbd> (or <kbd>↓</kbd> / <kbd>↑</kbd>)</td></tr><tr><td style="text-align:left;"><strong>Move Window Left / Right</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>Shift</kbd> + <kbd>H</kbd> / <kbd>L</kbd></td></tr><tr><td style="text-align:left;"><strong>Move Window Up / Down</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>Shift</kbd> + <kbd>J</kbd> / <kbd>K</kbd></td></tr><tr><td style="text-align:left;"><strong>Close Window</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>Q</kbd> (or <kbd>Mod</kbd> + <kbd>Shift</kbd> + <kbd>C</kbd>)</td></tr><tr><td style="text-align:left;"><strong>Fullscreen Toggle</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>F</kbd></td></tr><tr><td style="text-align:left;"><strong>Center Column</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>C</kbd></td></tr><tr><td style="text-align:left;"><strong>Expand / Shrink Width</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>R</kbd> / <kbd>Mod</kbd> + <kbd>Shift</kbd> + <kbd>R</kbd></td></tr></tbody></table><h3 id="workspace-monitors" tabindex="-1">Workspace &amp; Monitors <a class="header-anchor" href="#workspace-monitors" aria-label="Permalink to &quot;Workspace &amp; Monitors&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Keybinding</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Switch Workspace 1–8</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>1</kbd>–<kbd>8</kbd></td></tr><tr><td style="text-align:left;"><strong>Move Column to Workspace 1–8</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>Shift</kbd> + <kbd>1</kbd>–<kbd>8</kbd></td></tr><tr><td style="text-align:left;"><strong>Move Focus to Left/Right Monitor</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>Ctrl</kbd> + <kbd>H</kbd> / <kbd>L</kbd></td></tr></tbody></table><h3 id="application-launchers-system" tabindex="-1">Application Launchers &amp; System <a class="header-anchor" href="#application-launchers-system" aria-label="Permalink to &quot;Application Launchers &amp; System&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Keybinding</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Terminal (Ghostty)</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>Enter</kbd> (or <kbd>Mod</kbd> + <kbd>T</kbd>)</td></tr><tr><td style="text-align:left;"><strong>App Launcher (Fuzzel / Rofi)</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>Space</kbd> (or <kbd>Mod</kbd> + <kbd>D</kbd>)</td></tr><tr><td style="text-align:left;"><strong>Interactive Screenshot</strong></td><td style="text-align:left;"><kbd>PrintScreen</kbd> or <kbd>Mod</kbd> + <kbd>Shift</kbd> + <kbd>S</kbd></td></tr><tr><td style="text-align:left;"><strong>Lock Screen</strong></td><td style="text-align:left;"><kbd>Mod</kbd> + <kbd>Alt</kbd> + <kbd>L</kbd></td></tr></tbody></table><hr><h2 id="⚡-ghostty-terminal" tabindex="-1">⚡ Ghostty Terminal <a class="header-anchor" href="#⚡-ghostty-terminal" aria-label="Permalink to &quot;⚡ Ghostty Terminal&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Keybinding</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>New Tab</strong></td><td style="text-align:left;"><kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>T</kbd></td></tr><tr><td style="text-align:left;"><strong>Split Horizontally</strong></td><td style="text-align:left;"><kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>D</kbd></td></tr><tr><td style="text-align:left;"><strong>Split Vertically</strong></td><td style="text-align:left;"><kbd>Ctrl</kbd> + <kbd>Shift</kbd> + <kbd>E</kbd></td></tr><tr><td style="text-align:left;"><strong>Navigate Splits</strong></td><td style="text-align:left;"><kbd>Ctrl</kbd> + <kbd>Alt</kbd> + <kbd>H</kbd>/<kbd>J</kbd>/<kbd>K</kbd>/<kbd>L</kbd></td></tr></tbody></table><hr><h2 id="📝-helix-modal-editor" tabindex="-1">📝 Helix Modal Editor <a class="header-anchor" href="#📝-helix-modal-editor" aria-label="Permalink to &quot;📝 Helix Modal Editor&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Keybinding</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>File Picker</strong></td><td style="text-align:left;"><kbd>Space</kbd> + <kbd>f</kbd></td></tr><tr><td style="text-align:left;"><strong>Global Text Search</strong></td><td style="text-align:left;"><kbd>Space</kbd> + <kbd>/</kbd></td></tr><tr><td style="text-align:left;"><strong>Buffer / Open Tabs</strong></td><td style="text-align:left;"><kbd>Space</kbd> + <kbd>b</kbd></td></tr><tr><td style="text-align:left;"><strong>Save File</strong></td><td style="text-align:left;"><kbd>:w</kbd> + <kbd>Enter</kbd> or <kbd>Space</kbd> + <kbd>w</kbd></td></tr><tr><td style="text-align:left;"><strong>Quit</strong></td><td style="text-align:left;"><kbd>:q</kbd> + <kbd>Enter</kbd></td></tr></tbody></table>',17)])])}const y=d(a,[["render",r]]);export{h as __pageData,y as default};
